use eyre::{Result, bail};
use iota_graphql_client::Client;
use iota_transaction_builder::{MovePackageData, TransactionBuilder};
use iota_types::ObjectId;

#[tokio::main]
async fn main() -> Result<()> {
    // let client = Client::new_devnet();
    let client = Client::new_localnet();

    // let sender =
    // "0x1ca3c38e888493f869ac35346a2041d6cf87b0b935ebba14b35a08811d8a76e4".parse()?
    // ;
    let sender = "0x8bcf06501122587266e2c3b808a10b8df45d92e40768a34ad6f4a76248faf79e".parse()?;

    // let package_id =
    //     "0xb9d617f24c84826bf660a2f4031951678cc80c264aebc4413459fb2a95ada9ba".
    // parse()?;
    let package_id =
        "0x6a888f3955174a182aab178341ffb61a0cbe789aa74980acf90e9c5d2d06f9c6".parse()?;
    // let upgrade_cap =
    //     "0xd64205c4b10eff4b4adb00ab6f754cda8d8e7525985a31307f7e232481dfaf6e".
    // parse::<ObjectId>()?;
    let upgrade_cap =
        "0x753342ea0078818f5374cc06c9cb7ac6ae478c4a5dc5f907513eb62b004ec77e".parse::<ObjectId>()?;

    let mut builder = TransactionBuilder::new(sender).with_client(client.clone());
    builder.gas_budget(5_000_000);

    let data: MovePackageData = serde_json::from_str(SERIALIZED_MOVE_PACKAGE_DATA)?;
    println!("#Modules = {}", data.modules.len());
    println!("#Deps = {}", data.dependencies.len());
    println!("#Digest = {:?}", data.digest);

    builder.upgrade(package_id, upgrade_cap, data);

    let tx = builder.finish().await?;

    let res = client.dry_run_tx(&tx, false).await?;
    if let Some(err) = res.error {
        bail!("Dry run failed: {err}");
    }

    println!("Dry run succeeded");

    Ok(())
}

